contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        require(true);
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && address(c).balance == 0 && address(this).balance == selfBalBefore + cBalBefore);
    }

    receive() external payable {}
}

