    function run(bool asOwner) public payable {
        bool reverted;
        if (asOwner) {
            // make this contract the owner and selfdestruct succeeds
            c.sudicideAnyone();
            assert(address(c).balance == 0);
        } else {
            // cannot easily become non-owner because constructor of C sets msg.sender as owner
            // and this test contract is the deployer so it is the owner
