contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        require(c.sudicideAnyone.selector == bytes4(keccak256("sudicideAnyone()")));

        // The test contract is the deployer of c, hence the owner after construction.
        // A successful call must selfdestruct c: its code becomes empty and its balance is zero.
        address cAddr = address(c);
        uint256 balBefore = cAddr.balance;

        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }

        assert(
            (reverted && cAddr.code.length > 0 && cAddr.balance == balBefore) ||
            (!reverted && cAddr.code.length == 0 && cAddr.balance == 0)
        );
    }
}

