    function run(bool asOwner) public payable {
        address owner = address(this);
        require(owner == address(this), "owner check");

        // Drives c through the public entry sudicideAnyone. Since msg.sender is
        // this contract, which deployed c, it is the owner. The parameter only
        // ranges the input space; the owner path is always the one exercised.
        bool reverted;
        if (asOwner) {
