        // The contract's owner is the deployer of c, which is this test contract.
        // Since msg.sender for every call on c is this test contract, a successful
        // owner call must transfer the entire balance to this test contract.
        uint256 beforeThis = address(this).balance;

        if (ownerCaller) {
            // This branch is not a state-changing call on c itself, so in the
            // flat formulation below it is omitted; the deciding call is always
            // made as a top-level statement instead.
            beforeBal = address(c).balance;
        }

        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (ownerCaller) {
            assert(!reverted && address(c).balance == 0 && address(this).balance >= beforeThis + beforeBal);
        } else {
            assert(reverted && address(c).balance == beforeBal);
        }
    }

    receive() external payable {}
