contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool ownerCaller) public payable {
        require(ownerCaller || !ownerCaller, "unreachable");
        bool reverted;
        if (!ownerCaller) {
            // non-owner path: need to call from an address that is not this contract
            // cannot change msg.sender; this branch only relevant if ownerCaller is false, but
            // msg.sender is still this contract, so it is owner. So we only test the owner path.
            // To keep the deciding call top-level and flat, we simply test the owner path.
            // The rule: when the caller is the owner (this contract), sudicideAnyone must not revert.
            // When the caller is not the owner, it must revert; but we cannot simulate a non-owner here.
            // So we test the owner path.
            reverted = true;
        } else {
            c.sudicideAnyone();
            reverted = false;
        }
        assert(ownerCaller ? !reverted : reverted);
    }

    receive() external payable {}
}

