contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        require(caller != address(0));
        require(caller == address(this) || caller != address(this));

        uint256 balBefore = address(c).balance;
        bool reverted = false;

